function Stack() {
  let items = [];
  // 添加元素
  this.push = (element) => (items = [...items, element]);
  // 删除元素
  this.pop = () => items.pop();
  // 返回顶元素
  this.peek = () => items[items.length - 1];
  // 是否为空
  this.isEmpty = () => items.length === 0;
  // 清空
  this.clear = () => (items = []);
  // 元素个数
  this.size = () => items.length;
  // 打印
  this.print = () => items;
}



