function Queue() {
  let items = [];
  // 添加元素
  this.enqueue = (element) => (items = [...items, element]);
  // 删除元素
  this.dequeue = () => items.shift();
  // 第一个元素
  this.front = () => items[0];
  // 是否为空
  this.isEmpty = () => items.length === 0;
  // 元素个数
  this.size = () => items.length;
  // 打印
  this.print = () => items;
}

function PriorityQueue() {
  let items = [];
  // 添加元素
  this.enqueue = (element, priority) => {
    const obj = { element, priority };
    for (let i = 0; i < items.length; i++) {
      // 根据重要度插入到特定位置
      if (priority > items[i].priority) {
        return (items = [...items.slice(0, i), obj, ...items.slice(i)]);
      }
    }
    return (items = [...items, obj]);
    // 速度慢
    // items = [...items, obj].sort((a,b) => b.priority - a.priority)
  };
  // 删除元素
  this.dequeue = () => items.shift();
  // 第一个元素
  this.front = () => items[0];
  // 是否为空
  this.isEmpty = () => items.length === 0;
  // 元素个数
  this.size = () => items.length;
  // 打印
  this.print = () => items;
}



LinkedList#

function LinkedList() {
  function Node(element) {
    this.element = element;
    this.next = null;
  }
  let length = 0;
  let head;

  // 尾部添加
  this.append = (value) => {
    const element = new Node(value);
    if (head) {
      let current = head;
      while (current.next) {
        current = current.next;
      }
      current.next = element;
    } else {
      head = element;
    }
    length++;
  };

  // 特定位置插入
  this.insert = (position, value) => {
    const element = new Node(value);
    let index = 1;
    let current = head;
    let tmp;

    while (index < position) {
      current = current.next;
      index++;
    }
    length++;
    if (position === 0) {
      element.next = current;
      head = element;
    } else {
      tmp = current.next;
      current.next = element;
      current.next.next = tmp;
    }
  };

  // 特定位置移除一项
  this.removeAt = (position) => {
    let index = 0;
    let previos;
    let current = head;

    while (index < position) {
      previos = current;
      current = current.next;
      index++;
    }
    previos.next = current.next;

    length--;
  };

  // 移除一项
  this.remove = (value) => {
    let previos;
    let current = head;
    while (current.element !== value) {
      previos = current;
      current = current.next;
    }
    previos.next = current.next;
    length--;
  };

  // 返回索引
  this.indexOf = (value) => {
    let index = 0;
    let current = head;
    while (current.element !== value) {
      current = current.next;
      index++;
    }
    return index;
  };

  // 是否为空
  this.isEmpty = () => length === 0;

  // 元素个数
  this.size = () => length;

  // 获取链头
  this.getHead = () => head.element;

  // 打印
  this.print = () => head;
}



