      }
      .tip .t-row {
        display: flex;
        align-items: center;
        gap: 6px;
        margin-top: 3px;
      }
      .tip .t-key {
        width: 12px;
        height: 2px;
        border-radius: 1px;
        flex: none;
      }
      .tip .t-name {
        color: var(--ink-2);
      }
      .tip .t-val {
        margin-left: auto;
        font-weight: 600;
        color: var(--ink);
        font-variant-numeric: tabular-nums;
      }

      svg {
        display: block;
        width: 100%;
      }
      svg text {
        font-family:
          system-ui,
          -apple-system,
          "Segoe UI",
          sans-serif;
      }

      details.raw {
        margin-top: 16px;
      }
      details.raw summary {
        cursor: pointer;
        font-size: 13px;
        color: var(--ink-2);
        padding: 6px 0;
      }
      .raw-grid {
        display: grid;
        grid-template-columns: 260px 1fr;
        gap: 16px;
        margin-top: 10px;
      }
      .ep {
        display: block;
        width: 100%;
        padding: 9px 12px;
        border: 0;
        border-bottom: 1px solid var(--grid);
        background: transparent;
        color: var(--ink);
        text-align: left;
        cursor: pointer;
        font: inherit;
        font-size: 13px;
      }
      .ep:last-child {
        border-bottom: 0;
      }
      .ep:hover {
        background: var(--page);
      }
      .ep .p {
        font-family: ui-monospace, Menlo, monospace;
        font-size: 12.5px;
      }
      .ep .d {
        font-size: 11.5px;
        color: var(--muted);
      }
      pre {
        margin: 0;
        padding: 12px;
        max-height: 380px;
        overflow: auto;
        background: var(--page);
        border: 1px solid var(--border);
        border-radius: 8px;
        font-family: ui-monospace, Menlo, monospace;
        font-size: 12px;
        color: var(--ink-2);
        white-space: pre-wrap;
        word-break: break-all;
      }
    </style>
  </head>
