4    @EnableBatchProcessing 제거                           grep -rn 'EnableBatchProcessing' src/           조용히 Job 미실행 ★
5    javax.* → jakarta.*                                 grep -rn 'javax\.persistence|javax\.sql' src/   컴파일 에러
6    ItemWriter.write(List) → write(Chunk)               컴파일 에러                                          Step 08
